fn check(b:bool){if !b{let z=0;let _=1/z;}}struct S<'a,T>{s:&'a[T]}impl<'a,T> core::iter::Iterator for S<'a,T>{type Item=&'a T;fn next(&mut self)->Option<&'a T>{let s=self.s;match s{[first,rest @ ..]=>{self.s=rest;Some(first)},[]=>None}}}fn first<'a,T>(s:&'a[T])->Option<&'a T>{let mut i=S{s};let next:for<'b> fn(&'b mut S<'a,T>)->Option<&'a T>=<S<'a,T> as core::iter::Iterator>::next;next(&mut i)}fn main(){let a=[7u8];match first(&a){Some(x)=>check(*x==7),None=>check(false)}}
